window.v2Examples = {"reflection": "using System;\nusing System.Reflection;\n\nvar cat = new Cat { Name = \"Барсик\", Sleep = 16 };\nvar type = typeof(Cat);\nConsole.WriteLine($\"Тип: {type.Name}\");\nforeach (var property in type.GetProperties())\n{\n    Console.WriteLine($\"{property.Name}: {property.PropertyType.Name} = {property.GetValue(cat)}\");\n    var range = property.GetCustomAttribute<RandomRangeAttribute>();\n    if (range != null)\n        Console.WriteLine($\"  Настройка: от {range.Min} до {range.Max}\");\n}\nvar nameProperty = type.GetProperty(nameof(Cat.Name))!;\nnameProperty.SetValue(cat, \"Кусь\");\nConsole.WriteLine($\"Теперь имя: {cat.Name}\");\n\npublic class Cat\n{\n    public string Name { get; set; } = \"\";\n    [RandomRange(12, 20)]\n    public double Sleep { get; set; }\n}\n\n[AttributeUsage(AttributeTargets.Property)]\npublic class RandomRangeAttribute(double min, double max) : Attribute\n{\n    public double Min { get; } = min;\n    public double Max { get; } = max;\n}\n", "tree": "using System;\nusing System.Linq.Expressions;\n\nFunc<int, int> function = x => x + 1;\nExpression<Func<int, int>> tree = x => x + 1;\nConsole.WriteLine($\"Функция: {function(5)}\");\nConsole.WriteLine($\"Дерево: {tree}\");\nConsole.WriteLine($\"Действие: {tree.Body.NodeType}\");\nvar preparedFunction = tree.Compile();\nConsole.WriteLine($\"После Compile: {preparedFunction(5)}\");\n\n// То же дерево, но собираем сами.\nvar x = Expression.Parameter(typeof(int), \"x\");\nvar one = Expression.Constant(1);\nvar sum = Expression.Add(x, one);\nvar manualTree = Expression.Lambda<Func<int, int>>(sum, x);\nConsole.WriteLine($\"Собрали сами: {manualTree}\");\nConsole.WriteLine($\"Результат: {manualTree.Compile()(5)}\");\n", "factory": "using System;\nusing System.Linq.Expressions;\n\nIContinuousDistribution distribution = new UniformDistribution(12, 20);\n\n// 1. Будущий аргумент функции. Пока здесь нет конкретного Random.\nvar rnd = Expression.Parameter(typeof(Random), \"rnd\");\n// 2. Уже созданное распределение кладём внутрь дерева.\nvar distributionNode = Expression.Constant(distribution, typeof(IContinuousDistribution));\n// 3. Описание метода. Здесь его ещё НЕ вызываем.\nvar generateMethod = typeof(IContinuousDistribution)\n    .GetMethod(nameof(IContinuousDistribution.Generate))!;\n// 4. Будущий вызов distribution.Generate(rnd).\nvar generateCall = Expression.Call(distributionNode, generateMethod, rnd);\n// 5. Будущее присваивание Sleep = результат вызова.\nvar sleepProperty = typeof(Cat).GetProperty(nameof(Cat.Sleep))!;\nvar sleepBinding = Expression.Bind(sleepProperty, generateCall);\n// 6. Будущее создание new Cat { Sleep = ... }.\nvar body = Expression.MemberInit(Expression.New(typeof(Cat)), sleepBinding);\n// 7. Описание всей функции, затем подготовка делегата.\nvar tree = Expression.Lambda<Func<Random, Cat>>(body, rnd);\nConsole.WriteLine(tree);\nvar factory = tree.Compile();\n\n// Только теперь создаются коты и генерируются числа.\nvar random = new Random(42);\nfor (var i = 0; i < 3; i++)\n    Console.WriteLine($\"Кот {i + 1}: сон {factory(random).Sleep:F2}\");\n\npublic class Cat\n{\n    public double Sleep { get; set; }\n}\n\npublic interface IContinuousDistribution\n{\n    double Generate(Random rnd);\n}\n\n// Учебное распределение для отдельного показа, не замена распределений из домашки.\npublic class UniformDistribution(double min, double max) : IContinuousDistribution\n{\n    public double Generate(Random rnd) => min + rnd.NextDouble() * (max - min);\n}\n", "generic": "using System;\nusing System.Collections.Generic;\nusing System.Linq;\nusing System.Linq.Expressions;\nusing System.Reflection;\n\n\n\nvar random = new Random(42);\nvar cats = new Generator<Cat>();\nvar sensors = new Generator<SensorReading>();\nfor (var i = 0; i < 3; i++)\n{\n    var cat = cats.Generate(random);\n    var sensor = sensors.Generate(random);\n    Console.WriteLine($\"Кот: сон {cat.Sleep:F2}, наглость {cat.Audacity:F2}\");\n    Console.WriteLine($\"Датчик: температура {sensor.Temperature:F2}\");\n}\n\npublic class Cat\n{\n    [FromDistribution(typeof(UniformDistribution), 12.0, 20.0)]\n    public double Sleep { get; set; }\n    [FromDistribution(typeof(UniformDistribution), 1.0, 10.0)]\n    public double Audacity { get; set; }\n}\npublic class SensorReading\n{\n    [FromDistribution(typeof(UniformDistribution), -10.0, 30.0)]\n    public double Temperature { get; set; }\n}\npublic interface IContinuousDistribution\n{\n    double Generate(Random rnd);\n}\npublic class UniformDistribution(double min, double max) : IContinuousDistribution\n{\n    public double Generate(Random rnd) => min + rnd.NextDouble() * (max - min);\n}\n\npublic class Generator<T> where T : new()\n{\n    private readonly Func<Random, T> factory;\n\n    public Generator()\n    {\n        var distributions = CreateDistributionsFromAttributes();\n        factory = CreateFactory(distributions);\n    }\n\n    public T Generate(Random rnd) => factory(rnd);\n\n    private static Func<Random, T> CreateFactory(\n        Dictionary<PropertyInfo, IContinuousDistribution> distributions)\n    {\n        var rnd = Expression.Parameter(typeof(Random), \"rnd\");\n        var generateMethod = typeof(IContinuousDistribution)\n            .GetMethod(nameof(IContinuousDistribution.Generate))!;\n        var bindings = new List<MemberAssignment>();\n\n        foreach (var (property, distribution) in distributions)\n        {\n            var distributionNode = Expression.Constant(\n                distribution, typeof(IContinuousDistribution));\n            var generateCall = Expression.Call(distributionNode, generateMethod, rnd);\n            bindings.Add(Expression.Bind(property, generateCall));\n        }\n\n        var body = Expression.MemberInit(Expression.New(typeof(T)), bindings);\n        var tree = Expression.Lambda<Func<Random, T>>(body, rnd);\n        return tree.Compile();\n    }\n\n    private static Dictionary<PropertyInfo, IContinuousDistribution>\n        CreateDistributionsFromAttributes()\n    {\n        var result = new Dictionary<PropertyInfo, IContinuousDistribution>();\n        foreach (var property in typeof(T).GetProperties())\n        {\n            var attribute = property.GetCustomAttribute<FromDistributionAttribute>();\n            if (attribute == null) continue;\n            result.Add(property, CreateDistribution(attribute.Distribution, attribute.Parameters));\n        }\n        return result;\n    }\n\n    private static IContinuousDistribution CreateDistribution(Type type, object[] parameters)\n    {\n        if (!typeof(IContinuousDistribution).IsAssignableFrom(type))\n            throw new ArgumentException($\"{type.Name} must implement IContinuousDistribution\");\n        var parameterTypes = parameters.Select(p => p.GetType()).ToArray();\n        var constructor = type.GetConstructor(parameterTypes)\n            ?? throw new ArgumentException($\"Constructor not found for {type.Name}\");\n        return (IContinuousDistribution)constructor.Invoke(parameters);\n    }\n}\n\n[AttributeUsage(AttributeTargets.Property)]\npublic class FromDistributionAttribute(Type distribution, params object[] parameters) : Attribute\n{\n    public Type Distribution { get; } = distribution;\n    public object[] Parameters { get; } = parameters;\n}\n", "sql": "using System;\nusing System.Linq.Expressions;\n\nExpression<Func<Order, bool>> condition = order => order.Total > 1000m;\nConsole.WriteLine($\"Условие: {condition}\");\nvar comparison = (BinaryExpression)condition.Body;\nvar member = (MemberExpression)comparison.Left;\nvar constant = (ConstantExpression)comparison.Right;\nConsole.WriteLine($\"Операция: {comparison.NodeType}\");\nConsole.WriteLine($\"Свойство: {member.Member.Name}\");\nConsole.WriteLine($\"Значение: {constant.Value}\");\n\nvar (sql, parameter) = Translate(condition);\nConsole.WriteLine(sql);\nConsole.WriteLine($\"Параметр @p0: {parameter}\");\n\n// Учебная модель: только order.Total > число типа decimal.\n// Никакого подключения к базе здесь нет.\nstatic (string Sql, decimal Parameter) Translate(Expression<Func<Order, bool>> tree)\n{\n    if (tree.Body is not BinaryExpression { NodeType: ExpressionType.GreaterThan } comparison)\n        throw new ArgumentException(\"Поддерживаем только сравнение >\");\n    if (comparison.Left is not MemberExpression member\n        || member.Expression != tree.Parameters[0]\n        || member.Member.DeclaringType != typeof(Order)\n        || member.Member.Name != nameof(Order.Total))\n        throw new ArgumentException(\"Слева должно быть свойство order.Total\");\n    if (comparison.Right is not ConstantExpression { Value: decimal value })\n        throw new ArgumentException(\"Справа должно быть постоянное число decimal\");\n    return (\"WHERE [Total] > @p0\", value);\n}\n\npublic class Order\n{\n    public decimal Total { get; set; }\n}\n"};
